// Flashcards de Direito Processual Civil: reescritos a partir de Tabelas NEAF (material de Julia no Drive).
window.FC_VDE = (window.FC_VDE || []).concat([
{"id": "tj_cpc_001", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Até que grau de parentesco o juiz fica impedido quando o parente atua no processo como advogado, defensor público ou membro do MP?", "v": "Até o 3º grau, inclusive, em linha reta ou colateral, consanguíneo ou afim; vale também para cônjuge ou companheiro.", "b": "CPC, art. 144, III"},
{"id": "tj_cpc_002", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Quando o parente do juiz atua como advogado, em que caso surge o impedimento previsto no art. 144, III?", "v": "Só quando esse advogado, defensor ou membro do MP já atuava no processo antes de o juiz começar a funcionar nele.", "b": "CPC, art. 144, § 1º", "p": "Se o parente entra depois que o juiz já atua, não há impedimento por esse inciso."},
{"id": "tj_cpc_003", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "O impedimento do art. 144, III alcança o caso em que o mandato foi dado a escritório que tem o parente do juiz entre seus advogados?", "v": "Sim, mesmo que esse advogado não atue diretamente no processo.", "b": "CPC, art. 144, § 3º"},
{"id": "tj_cpc_004", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Receber presentes de interessados na causa gera impedimento ou suspeição do juiz? Importa o momento?", "v": "Gera suspeição, tanto se o presente for recebido antes quanto depois de iniciado o processo.", "b": "CPC, art. 145, II", "p": "É hipótese de suspeição, não de impedimento."},
{"id": "tj_cpc_005", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Qual o prazo para a parte alegar impedimento ou suspeição do juiz, e como?", "v": "15 dias contados do conhecimento do fato, em petição específica dirigida ao juiz do processo, com o fundamento da recusa.", "b": "CPC, art. 146"},
{"id": "tj_cpc_006", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Se o juiz não reconhecer o impedimento ou a suspeição alegados, em quanto tempo apresenta suas razões?", "v": "Em 15 dias, mandando autuar a petição em apartado e remetendo o incidente ao tribunal.", "b": "CPC, art. 146, § 1º"},
{"id": "tj_cpc_007", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Recebido o incidente de impedimento/suspeição sem efeito suspensivo, o que ocorre com o processo? E com efeito suspensivo?", "v": "Sem efeito suspensivo, o processo volta a correr; com efeito suspensivo, fica suspenso até o julgamento do incidente.", "b": "CPC, art. 146, § 2º"},
{"id": "tj_cpc_008", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Enquanto não declarado o efeito do incidente de impedimento/suspeição, a quem se pede tutela de urgência?", "v": "Ao substituto legal do juiz.", "b": "CPC, art. 146, § 3º"},
{"id": "tj_cpc_009", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Dois juízes parentes até o 3º grau: qual deles fica impedido de atuar no processo?", "v": "O segundo: o primeiro que conhecer do processo impede a atuação do outro, que se escusa e remete os autos ao substituto legal.", "b": "CPC, art. 147"},
{"id": "tj_cpc_010", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Qual o prazo para o membro do MP, auxiliar da justiça ou outro sujeito arguido se manifestar no incidente de impedimento/suspeição?", "v": "15 dias; o incidente corre em separado e sem suspensão do processo.", "b": "CPC, art. 148, § 2º"},
{"id": "tj_cpc_011", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Quantos oficiais de justiça deve haver, no mínimo, em cada comarca, seção ou subseção?", "v": "Pelo menos tantos quantos forem os juízos.", "b": "CPC, art. 151"},
{"id": "tj_cpc_012", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "A ordem cronológica de publicação e efetivação dos pronunciamentos atendida pelo escrivão é obrigatória ou preferencial?", "v": "Preferencial. A lista dos processos recebidos fica disponível de forma permanente para consulta pública.", "b": "CPC, art. 153 e § 1º", "p": "A lei diz \"preferencialmente\", não obrigatoriamente."},
{"id": "tj_cpc_013", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Quais atos ficam fora da regra da ordem cronológica do escrivão?", "v": "Os atos urgentes reconhecidos pelo juiz e as preferências legais (que seguem ordem cronológica própria entre si).", "b": "CPC, art. 153, §§ 2º e 3º"},
{"id": "tj_cpc_014", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "A parte preterida na ordem cronológica reclama ao juiz; em quanto tempo o servidor presta informações?", "v": "Em 2 dias. Constatada a preterição, o juiz manda cumprir o ato de imediato e instaurar processo administrativo disciplinar.", "b": "CPC, art. 153, §§ 4º e 5º"},
{"id": "tj_cpc_015", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Na presença de quantas testemunhas o oficial de justiça deve realizar citações, penhoras e demais diligências?", "v": "De 2 testemunhas, sempre que possível.", "b": "CPC, art. 154, I"},
{"id": "tj_cpc_016", "d": "Direito Processual Civil", "t": "Impedimento, suspeição e auxiliares da justiça", "r": "1", "f": "Certificada pelo oficial uma proposta de autocomposição, qual o prazo da parte contrária e o que significa o seu silêncio?", "v": "5 dias, sem prejuízo do andamento do processo; o silêncio vale como recusa.", "b": "CPC, art. 154, parágrafo único", "p": "Silêncio é recusa, não aceitação."},
{"id": "tj_cpc_017", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Quais os requisitos para o negócio jurídico processual atípico (mudança do procedimento pelas partes)?", "v": "Direitos que admitam autocomposição e partes plenamente capazes; pode ser feito antes ou durante o processo.", "b": "CPC, art. 190"},
{"id": "tj_cpc_018", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "O calendário processual fixado por juiz e partes pode ter seus prazos alterados?", "v": "Só em casos excepcionais e devidamente justificados; ele vincula partes e juiz.", "b": "CPC, art. 191, § 1º"},
{"id": "tj_cpc_019", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "É preciso intimar as partes para atos cujas datas já constam do calendário processual?", "v": "Não, a intimação é dispensada.", "b": "CPC, art. 191, § 2º"},
{"id": "tj_cpc_020", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Quando a desistência da ação passa a produzir efeitos?", "v": "Somente depois da homologação judicial.", "b": "CPC, art. 200, parágrafo único", "p": "É exceção à regra de que os atos das partes produzem efeitos imediatamente."},
{"id": "tj_cpc_021", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Qual a multa para quem lança cotas marginais ou interlineares nos autos?", "v": "Metade do salário mínimo, além de o juiz mandar riscá-las.", "b": "CPC, art. 202"},
{"id": "tj_cpc_022", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Juntada e vista obrigatória dependem de despacho do juiz?", "v": "Não. São atos meramente ordinatórios, praticados de ofício pelo servidor e revistos pelo juiz quando necessário.", "b": "CPC, art. 203, § 4º"},
{"id": "tj_cpc_023", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Em que dias e horários se realizam os atos processuais?", "v": "Em dias úteis, das 6 às 20 horas.", "b": "CPC, art. 212"},
{"id": "tj_cpc_024", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Um ato iniciado antes das 20 horas pode terminar depois desse horário?", "v": "Sim, se o adiamento prejudicar a diligência ou causar grave dano.", "b": "CPC, art. 212, § 1º"},
{"id": "tj_cpc_025", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Citações, intimações e penhoras nas férias, feriados ou fora do horário precisam de autorização judicial?", "v": "Não, independem de autorização, respeitada a inviolabilidade do domicílio (CF, art. 5º, XI).", "b": "CPC, art. 212, § 2º"},
{"id": "tj_cpc_026", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Até que horário pode ser praticado um ato processual eletrônico no último dia do prazo, e qual fuso vale?", "v": "Até as 24 horas do último dia, considerando o horário vigente no juízo onde o ato deve ser praticado.", "b": "CPC, art. 213 e parágrafo único"},
{"id": "tj_cpc_027", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Quais processos correm durante as férias forenses e não se suspendem por elas?", "v": "Os de jurisdição voluntária e os de conservação de direitos que o adiamento prejudique; ação de alimentos; nomeação ou remoção de tutor e curador; e outros que a lei determinar.", "b": "CPC, art. 215"},
{"id": "tj_cpc_028", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Além dos feriados legais, que dias são feriados para efeito forense?", "v": "Os sábados, os domingos e os dias sem expediente forense.", "b": "CPC, art. 216"},
{"id": "tj_cpc_029", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Se a lei e o juiz não fixarem prazo, em quanto tempo a intimação obriga o comparecimento?", "v": "Somente depois de decorridas 48 horas.", "b": "CPC, art. 218, § 2º"},
{"id": "tj_cpc_030", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Sem previsão legal nem fixação pelo juiz, qual o prazo para a parte praticar um ato?", "v": "5 dias.", "b": "CPC, art. 218, § 3º"},
{"id": "tj_cpc_031", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Ato praticado antes do início do prazo é intempestivo?", "v": "Não; é considerado tempestivo.", "b": "CPC, art. 218, § 4º"},
{"id": "tj_cpc_032", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Como se contam os prazos processuais fixados em dias?", "v": "Computando somente os dias úteis; a regra vale apenas para prazos processuais.", "b": "CPC, art. 219"},
{"id": "tj_cpc_033", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Em que período fica suspenso o curso dos prazos processuais no fim do ano?", "v": "De 20 de dezembro a 20 de janeiro, inclusive; nesse período não há audiências nem sessões de julgamento.", "b": "CPC, art. 220 e § 2º", "p": "Juízes, MP, Defensoria, Advocacia Pública e auxiliares continuam trabalhando, ressalvadas férias individuais e feriados."},
{"id": "tj_cpc_034", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Suspenso o prazo por obstáculo criado contra a parte, como ele é devolvido?", "v": "É restituído por tempo igual ao que faltava para completá-lo.", "b": "CPC, art. 221"},
{"id": "tj_cpc_035", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Onde o transporte for difícil, por quanto tempo o juiz pode prorrogar os prazos?", "v": "Por até 2 meses; em calamidade pública esse limite pode ser excedido.", "b": "CPC, art. 222 e § 2º"},
{"id": "tj_cpc_036", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "O juiz pode reduzir prazos peremptórios?", "v": "Só com a anuência das partes.", "b": "CPC, art. 222, § 1º"},
{"id": "tj_cpc_037", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Como se contam os dias de início e de fim do prazo?", "v": "Exclui-se o dia do começo e inclui-se o dia do vencimento, salvo disposição em contrário.", "b": "CPC, art. 224"},
{"id": "tj_cpc_038", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Quando se considera publicada a informação disponibilizada no Diário da Justiça eletrônico, e quando o prazo começa?", "v": "Publicação: 1º dia útil seguinte à disponibilização. O prazo começa no 1º dia útil seguinte ao da publicação.", "b": "CPC, art. 224, §§ 2º e 3º"},
{"id": "tj_cpc_039", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Quais os prazos do juiz para despachos, decisões interlocutórias e sentenças?", "v": "Despachos em 5 dias, decisões interlocutórias em 10 dias e sentenças em 30 dias.", "b": "CPC, art. 226"},
{"id": "tj_cpc_040", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Havendo motivo justificado, o juiz pode exceder seus prazos? Por quanto tempo?", "v": "Sim, por igual tempo, em qualquer grau de jurisdição.", "b": "CPC, art. 227"},
{"id": "tj_cpc_041", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Quais os prazos do serventuário para remeter os autos conclusos e para executar os atos processuais?", "v": "1 dia para a conclusão e 5 dias para executar os atos.", "b": "CPC, art. 228"},
{"id": "tj_cpc_042", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Litisconsortes com procuradores diferentes têm prazo em dobro? Precisa pedir?", "v": "Sim, desde que os procuradores sejam de escritórios distintos; o dobro vale em qualquer juízo ou tribunal e independe de requerimento.", "b": "CPC, art. 229"},
{"id": "tj_cpc_043", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Quando cessa o prazo em dobro dos litisconsortes?", "v": "Se, havendo apenas 2 réus, só um deles oferecer defesa.", "b": "CPC, art. 229, § 1º"},
{"id": "tj_cpc_044", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Qual o dia do começo do prazo quando a citação ou intimação é feita pelo correio? E por oficial de justiça?", "v": "Correio: data de juntada do aviso de recebimento. Oficial: data de juntada do mandado cumprido.", "b": "CPC, art. 231, I e II"},
{"id": "tj_cpc_045", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Qual o dia do começo do prazo na citação por edital e na citação eletrônica?", "v": "Edital: dia útil seguinte ao fim da dilação fixada pelo juiz. Eletrônica: dia útil seguinte à consulta ou ao fim do prazo para consultar.", "b": "CPC, art. 231, IV e V"},
{"id": "tj_cpc_046", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Havendo vários réus, quando começa o prazo para contestar? E havendo vários intimados?", "v": "Para contestar, da última das datas dos incisos I a VI do art. 231. Para vários intimados, o prazo de cada um corre individualmente.", "b": "CPC, art. 231, §§ 1º e 2º"},
{"id": "tj_cpc_047", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Advogado intimado que não devolve os autos em quanto tempo sofre sanção? Qual?", "v": "Em 3 dias; perde o direito de vista fora de cartório e paga multa de metade do salário mínimo.", "b": "CPC, art. 234, § 2º"},
{"id": "tj_cpc_048", "d": "Direito Processual Civil", "t": "Atos processuais: negócio jurídico processual, forma, tempo, lugar e prazos", "r": "1", "f": "Na representação contra juiz que excede prazos, qual o prazo para a justificativa e, depois, para praticar o ato?", "v": "15 dias para justificar; em seguida, intimação para praticar o ato em 10 dias. Mantida a inércia, o substituto legal decide em 10 dias.", "b": "CPC, art. 235, §§ 1º a 3º"},
{"id": "tj_cpc_049", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Em quanto tempo deve ser efetivada a citação a partir da propositura da ação?", "v": "Em até 45 dias.", "b": "CPC, art. 238, parágrafo único"},
{"id": "tj_cpc_050", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "O comparecimento espontâneo do réu supre a falta de citação? Quando corre o prazo de defesa?", "v": "Sim, supre a falta ou a nulidade; o prazo para contestar ou embargar corre a partir desse comparecimento.", "b": "CPC, art. 239, § 1º"},
{"id": "tj_cpc_051", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Citação ordenada por juízo incompetente produz os efeitos de litispendência, litigiosidade e mora?", "v": "Sim, a citação válida produz esses efeitos mesmo vinda de juízo incompetente.", "b": "CPC, art. 240"},
{"id": "tj_cpc_052", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "A interrupção da prescrição pelo despacho que ordena a citação retroage a quando? Em quanto tempo o autor deve viabilizar a citação?", "v": "Retroage à data da propositura da ação; o autor tem 10 dias para tomar as providências, sob pena de perder a retroação.", "b": "CPC, art. 240, §§ 1º e 2º"},
{"id": "tj_cpc_053", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Durante quanto tempo não se cita o cônjuge ou parente do morto (salvo para evitar perecimento do direito)?", "v": "No dia do falecimento e nos 7 dias seguintes (parentes em linha reta ou colateral em 2º grau).", "b": "CPC, art. 244, II"},
{"id": "tj_cpc_054", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Por quantos dias não se citam os noivos após o casamento?", "v": "Nos 3 primeiros dias seguintes ao casamento.", "b": "CPC, art. 244, III"},
{"id": "tj_cpc_055", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Qual o prazo do médico nomeado para examinar citando que aparenta incapacidade?", "v": "5 dias para apresentar o laudo.", "b": "CPC, art. 245, § 2º"},
{"id": "tj_cpc_056", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Qual o prazo para realizar a citação por meio eletrônico?", "v": "Até 2 dias úteis contados da decisão que a determinar.", "b": "CPC, art. 246"},
{"id": "tj_cpc_057", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Se o citando não confirma a citação eletrônica, em que prazo e o que acontece?", "v": "Sem confirmação em até 3 dias úteis do recebimento, a citação é feita pelo correio, por oficial, pelo escrivão (se comparecer em cartório) ou por edital.", "b": "CPC, art. 246, § 1º-A"},
{"id": "tj_cpc_058", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Qual a multa por deixar de confirmar, sem justa causa, o recebimento da citação eletrônica?", "v": "Até 5% do valor da causa, por ato atentatório à dignidade da justiça.", "b": "CPC, art. 246, § 1º-C"},
{"id": "tj_cpc_059", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Em que casos não se faz a citação por meio eletrônico ou pelo correio?", "v": "Ações de estado; citando incapaz; pessoa de direito público; local sem entrega domiciliar de correspondência; ou quando o autor, justificadamente, pedir outra forma.", "b": "CPC, art. 247"},
{"id": "tj_cpc_060", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Quando o oficial de justiça pode fazer a citação com hora certa?", "v": "Quando procurar o citando 2 vezes no domicílio ou residência sem encontrá-lo e houver suspeita de ocultação; volta no dia útil imediato.", "b": "CPC, art. 252"},
{"id": "tj_cpc_061", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Feita a citação com hora certa, qual o prazo para o escrivão enviar a comunicação ao réu?", "v": "10 dias contados da juntada do mandado aos autos.", "b": "CPC, art. 254"},
{"id": "tj_cpc_062", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Qual o prazo do edital de citação fixado pelo juiz?", "v": "Entre 20 e 60 dias, contado da publicação única ou da primeira, se houver mais de uma.", "b": "CPC, art. 257, III"},
{"id": "tj_cpc_063", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Qual a multa para quem pede citação por edital alegando dolosamente seus requisitos, e quem recebe?", "v": "5 vezes o salário mínimo, em benefício do citando.", "b": "CPC, art. 258"},
{"id": "tj_cpc_064", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Em quanto tempo a carta cumprida é devolvida ao juízo de origem?", "v": "Em 10 dias, sem traslado, pagas as custas pela parte.", "b": "CPC, art. 268"},
{"id": "tj_cpc_065", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "O que significa dizer que a carta tem caráter itinerante?", "v": "Antes ou depois de ordenado o cumprimento, pode ser enviada a juízo diverso do indicado para praticar o ato, comunicando-se o órgão expedidor.", "b": "CPC, art. 262"},
{"id": "tj_cpc_066", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Em que casos o juiz recusa cumprimento a carta precatória ou arbitral?", "v": "Se faltarem requisitos legais, se ele não tiver competência em razão da matéria ou da hierarquia, ou se duvidar da autenticidade.", "b": "CPC, art. 267"},
{"id": "tj_cpc_067", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "A retirada dos autos em carga pelo advogado produz intimação? De quê?", "v": "Sim, de qualquer decisão contida no processo, ainda que pendente de publicação.", "b": "CPC, art. 272, § 6º"},
{"id": "tj_cpc_068", "d": "Direito Processual Civil", "t": "Comunicação dos atos: citação, cartas e intimação", "r": "1", "f": "Mudança de endereço não comunicada ao juízo: a intimação enviada ao endereço antigo vale?", "v": "Vale; presume-se válida e o prazo corre da juntada do comprovante de entrega no endereço primitivo.", "b": "CPC, art. 274, parágrafo único"},
{"id": "tj_cpc_069", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "A tutela provisória de urgência pode ser pedida em que caráter?", "v": "Antecedente ou incidental, tanto a cautelar quanto a antecipada.", "b": "CPC, art. 294, parágrafo único"},
{"id": "tj_cpc_070", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "A tutela provisória mantém eficácia durante a suspensão do processo?", "v": "Sim, salvo decisão judicial em contrário; e pode ser revogada ou modificada a qualquer tempo.", "b": "CPC, art. 296 e parágrafo único"},
{"id": "tj_cpc_071", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "A caução exigida para conceder tutela de urgência pode ser dispensada?", "v": "Sim, se a parte economicamente hipossuficiente não puder oferecê-la.", "b": "CPC, art. 300, § 1º"},
{"id": "tj_cpc_072", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "Quando não se concede tutela de urgência de natureza antecipada?", "v": "Quando houver perigo de irreversibilidade dos efeitos da decisão.", "b": "CPC, art. 300, § 3º"},
{"id": "tj_cpc_073", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "Obtida liminarmente a tutela antecedente, em que prazo o autor deve fornecer os meios para citar o réu, sob pena de responder pelo prejuízo?", "v": "5 dias.", "b": "CPC, art. 302, II"},
{"id": "tj_cpc_074", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "Concedida a tutela antecipada antecedente, em quanto tempo o autor adita a petição inicial?", "v": "Em 15 dias ou em prazo maior fixado pelo juiz, nos mesmos autos e sem novas custas; sem aditamento, o processo é extinto sem mérito.", "b": "CPC, art. 303, §§ 1º a 3º"},
{"id": "tj_cpc_075", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "Se o juiz entender que não há elementos para a tutela antecipada antecedente, qual o prazo de emenda?", "v": "Até 5 dias, sob pena de indeferimento e extinção sem resolução do mérito.", "b": "CPC, art. 303, § 6º", "p": "Aqui são 5 dias, não os 15 dias da emenda da inicial comum (art. 321)."},
{"id": "tj_cpc_076", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "Quando a tutela antecipada antecedente se torna estável?", "v": "Quando não se interpõe recurso contra a decisão que a concedeu; o processo é extinto.", "b": "CPC, art. 304 e § 1º"},
{"id": "tj_cpc_077", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "Qual o prazo para rever, reformar ou invalidar a tutela antecipada estabilizada?", "v": "2 anos, contados da ciência da decisão que extinguiu o processo.", "b": "CPC, art. 304, § 5º"},
{"id": "tj_cpc_078", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "Na tutela cautelar antecedente, qual o prazo de contestação do réu? E se ele não contestar?", "v": "5 dias para contestar e indicar provas; sem contestação, os fatos se presumem aceitos e o juiz decide em 5 dias.", "b": "CPC, arts. 306 e 307"},
{"id": "tj_cpc_079", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "Efetivada a tutela cautelar antecedente, em quanto tempo deve ser formulado o pedido principal?", "v": "Em 30 dias, nos mesmos autos e sem adiantar novas custas.", "b": "CPC, art. 308"},
{"id": "tj_cpc_080", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "Quando cessa a eficácia da tutela cautelar antecedente?", "v": "Se o pedido principal não for feito no prazo legal ou se a medida não for efetivada em 30 dias .", "b": "CPC, art. 309, I e II"},
{"id": "tj_cpc_081", "d": "Direito Processual Civil", "t": "Tutela provisória", "r": "1", "f": "Cessada a eficácia da tutela cautelar, a parte pode renovar o pedido?", "v": "Não, salvo com novo fundamento.", "b": "CPC, art. 309, parágrafo único"},
{"id": "tj_cpc_082", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Qual o prazo para o autor emendar ou completar a petição inicial defeituosa?", "v": "15 dias, devendo o juiz indicar com precisão o que corrigir; se não cumprir, a inicial é indeferida.", "b": "CPC, art. 321"},
{"id": "tj_cpc_083", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Até quando o autor pode alterar pedido ou causa de pedir sem e com consentimento do réu?", "v": "Sem consentimento, até a citação; com consentimento, até o saneamento, assegurado ao réu manifestar-se em no mínimo 15 dias.", "b": "CPC, art. 329"},
{"id": "tj_cpc_084", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Indeferida a petição inicial e interposta apelação, em quanto tempo o juiz pode se retratar?", "v": "Em 5 dias.", "b": "CPC, art. 331"},
{"id": "tj_cpc_085", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Em que hipóteses o juiz julga liminarmente improcedente o pedido, sem citar o réu?", "v": "Quando contrariar súmula do STF/STJ, repetitivo do STF/STJ, IRDR ou assunção de competência, ou súmula do TJ sobre direito local; e se verificar prescrição ou decadência.", "b": "CPC, art. 332 e § 1º"},
{"id": "tj_cpc_086", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Na improcedência liminar, qual o prazo de retratação do juiz após a apelação e o de contrarrazões do réu?", "v": "5 dias para retratação; não havendo, o réu é citado para contrarrazões em 15 dias.", "b": "CPC, art. 332, §§ 3º e 4º"},
{"id": "tj_cpc_087", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Com que antecedência mínima se marca a audiência de conciliação/mediação e se cita o réu?", "v": "Audiência com pelo menos 30 dias de antecedência; citação do réu com pelo menos 20 dias.", "b": "CPC, art. 334"},
{"id": "tj_cpc_088", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Pode haver mais de uma sessão de conciliação/mediação? Qual o limite?", "v": "Sim, sem passar de 2 meses da data da primeira sessão.", "b": "CPC, art. 334, § 2º"},
{"id": "tj_cpc_089", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Quando a audiência de conciliação não é realizada?", "v": "Se ambas as partes manifestarem expressamente desinteresse ou se não for admitida autocomposição.", "b": "CPC, art. 334, § 4º", "p": "O desinteresse de só uma das partes não basta; com litisconsórcio, todos precisam manifestar."},
{"id": "tj_cpc_090", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Com que antecedência o réu deve informar seu desinteresse na autocomposição?", "v": "Por petição com 10 dias de antecedência da audiência; o autor indica o desinteresse já na inicial.", "b": "CPC, art. 334, § 5º"},
{"id": "tj_cpc_091", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Qual a sanção para a ausência injustificada à audiência de conciliação?", "v": "Multa de até 2% da vantagem econômica pretendida ou do valor da causa, revertida à União ou ao Estado, por ato atentatório à dignidade da justiça.", "b": "CPC, art. 334, § 8º"},
{"id": "tj_cpc_092", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Qual o intervalo mínimo entre as audiências de conciliação na pauta?", "v": "20 minutos entre o início de uma e o da seguinte.", "b": "CPC, art. 334, § 12", "p": "Na pauta da instrução e julgamento o intervalo é de 1 hora (art. 357, § 9º)."},
{"id": "tj_cpc_093", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Qual o prazo de contestação e a partir de quando corre, em regra?", "v": "15 dias, contados da audiência de conciliação (ou da última sessão) sem acordo, do protocolo do pedido de cancelamento pelo réu, ou conforme o art. 231 nos demais casos.", "b": "CPC, art. 335"},
{"id": "tj_cpc_094", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Quais matérias do art. 337 o juiz não pode conhecer de ofício?", "v": "A convenção de arbitragem e a incompetência relativa.", "b": "CPC, art. 337, § 5º"},
{"id": "tj_cpc_095", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Qual a diferença entre litispendência e coisa julgada?", "v": "Nas duas se reproduz ação já ajuizada; há litispendência quando a ação repetida ainda está em curso.", "b": "CPC, art. 337, §§ 1º e 3º"},
{"id": "tj_cpc_096", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Alegada ilegitimidade pelo réu, qual o prazo para o autor substituí-lo e quanto paga de honorários ao réu excluído?", "v": "15 dias para alterar a inicial; honorários entre 3% e 5% do valor da causa (ou por equidade, se irrisório).", "b": "CPC, art. 338"},
{"id": "tj_cpc_097", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Em caso de incompetência alegada, onde a contestação pode ser protocolada?", "v": "No foro de domicílio do réu, comunicando-se o juiz da causa; a audiência de conciliação designada fica suspensa.", "b": "CPC, art. 340 e § 3º"},
{"id": "tj_cpc_098", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Proposta reconvenção, qual o prazo de resposta do autor reconvindo?", "v": "15 dias, intimado na pessoa de seu advogado.", "b": "CPC, art. 343, § 1º"},
{"id": "tj_cpc_099", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "A desistência da ação impede o prosseguimento da reconvenção?", "v": "Não; a reconvenção prossegue.", "b": "CPC, art. 343, § 2º"},
{"id": "tj_cpc_100", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Havendo vários réus e um deles contesta, a revelia produz o efeito de presumir verdadeiros os fatos?", "v": "Não; a contestação de um dos réus afasta esse efeito.", "b": "CPC, art. 345, I"},
{"id": "tj_cpc_101", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Contra o revel sem advogado nos autos, de quando correm os prazos?", "v": "Da publicação do ato decisório no órgão oficial; o revel pode intervir em qualquer fase, recebendo o processo no estado em que estiver.", "b": "CPC, art. 346 e parágrafo único"},
{"id": "tj_cpc_102", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Alegado pelo réu fato impeditivo, modificativo ou extintivo, ou matéria do art. 337, qual o prazo de réplica do autor?", "v": "15 dias, com possibilidade de produzir prova.", "b": "CPC, arts. 350 e 351"},
{"id": "tj_cpc_103", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "Qual o prazo máximo para corrigir irregularidades ou vícios sanáveis nas providências preliminares?", "v": "Nunca superior a 30 dias.", "b": "CPC, art. 352"},
{"id": "tj_cpc_104", "d": "Direito Processual Civil", "t": "Procedimento comum: petição inicial, audiência de conciliação e contestação", "r": "1", "f": "A decisão que julga parcialmente o mérito pode ser executada mesmo com recurso pendente?", "v": "Sim, desde logo e sem caução; com o trânsito em julgado, a execução passa a ser definitiva.", "b": "CPC, art. 356, §§ 2º e 3º"},
{"id": "tj_cpc_105", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "Feito o saneamento, qual o prazo para as partes pedirem esclarecimentos ou ajustes?", "v": "Prazo comum de 5 dias; depois disso a decisão se torna estável.", "b": "CPC, art. 357, § 1º"},
{"id": "tj_cpc_106", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "Qual o prazo para apresentar rol de testemunhas fixado no saneamento?", "v": "Prazo comum não superior a 15 dias.", "b": "CPC, art. 357, § 4º"},
{"id": "tj_cpc_107", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "Quantas testemunhas cada parte pode arrolar?", "v": "No máximo 10, sendo no máximo 3 para cada fato; o juiz pode limitar conforme a complexidade.", "b": "CPC, art. 357, §§ 6º e 7º"},
{"id": "tj_cpc_108", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "Qual o intervalo mínimo entre as audiências de instrução na pauta?", "v": "1 hora.", "b": "CPC, art. 357, § 9º"},
{"id": "tj_cpc_109", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "Atraso de quanto tempo no início da audiência permite seu adiamento?", "v": "Atraso injustificado superior a 30 minutos do horário marcado.", "b": "CPC, art. 362, III"},
{"id": "tj_cpc_110", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "Nos debates orais, quanto tempo tem cada advogado e o MP?", "v": "20 minutos para cada um, prorrogáveis por 10 minutos a critério do juiz.", "b": "CPC, art. 364"},
{"id": "tj_cpc_111", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "Em causa complexa, os debates orais podem ser substituídos por quê, e em que prazo?", "v": "Por razões finais escritas, em prazos sucessivos de 15 dias para autor, réu e MP.", "b": "CPC, art. 364, § 2º"},
{"id": "tj_cpc_112", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "A audiência de instrução pode ser dividida?", "v": "É una e contínua, mas pode ser cindida excepcionalmente na ausência de perito ou testemunha, se as partes concordarem.", "b": "CPC, art. 365"},
{"id": "tj_cpc_113", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "Após os debates ou razões finais, em quanto tempo o juiz sentencia?", "v": "Na própria audiência ou em 30 dias.", "b": "CPC, art. 366"},
{"id": "tj_cpc_114", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "A parte pode gravar a audiência sem autorização do juiz?", "v": "Sim, a gravação pode ser feita diretamente por qualquer das partes, independentemente de autorização judicial.", "b": "CPC, art. 367, § 6º"},
{"id": "tj_cpc_115", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "O juiz pode usar prova produzida em outro processo?", "v": "Sim, atribuindo-lhe o valor que considerar adequado, observado o contraditório.", "b": "CPC, art. 372"},
{"id": "tj_cpc_116", "d": "Direito Processual Civil", "t": "Audiência de instrução e julgamento e teoria geral da prova", "r": "1", "f": "Quando a convenção das partes sobre distribuição do ônus da prova não é admitida?", "v": "Quando recair sobre direito indisponível ou tornar excessivamente difícil o exercício do direito; pode ser feita antes ou durante o processo.", "b": "CPC, art. 373, §§ 3º e 4º"},
{"id": "tj_cpc_117", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "A produção antecipada de prova previne a competência para a ação futura?", "v": "Não previne.", "b": "CPC, art. 381, § 3º"},
{"id": "tj_cpc_118", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Na produção antecipada de prova cabe defesa ou recurso?", "v": "Não, salvo contra decisão que indeferir totalmente a prova pedida pelo requerente originário.", "b": "CPC, art. 382, § 4º"},
{"id": "tj_cpc_119", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Por quanto tempo os autos da produção antecipada ficam em cartório para cópias?", "v": "Durante 1 mês; depois são entregues ao promovente.", "b": "CPC, art. 383"},
{"id": "tj_cpc_120", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "A confissão pode ser revogada?", "v": "Não, é irrevogável; mas pode ser anulada se resultou de erro de fato ou coação.", "b": "CPC, art. 393"},
{"id": "tj_cpc_121", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Na exibição de documento pela parte, qual o prazo de resposta do requerido? E se o documento estiver com terceiro?", "v": "Parte: 5 dias após a intimação. Terceiro: é citado para responder em 15 dias.", "b": "CPC, arts. 398 e 401"},
{"id": "tj_cpc_122", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Terceiro que se recusa sem justo motivo a exibir documento: qual o prazo para depositá-lo?", "v": "5 dias, em cartório ou outro lugar designado.", "b": "CPC, art. 403"},
{"id": "tj_cpc_123", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Qual o prazo para suscitar a falsidade de documento?", "v": "Na contestação, na réplica ou em 15 dias da intimação da juntada do documento.", "b": "CPC, art. 430"},
{"id": "tj_cpc_124", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Juntado documento por uma parte, qual o prazo da outra para se manifestar?", "v": "15 dias, podendo o juiz dilatá-lo conforme a quantidade e complexidade dos documentos.", "b": "CPC, art. 437, §§ 1º e 2º"},
{"id": "tj_cpc_125", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Quem é incapaz para depor como testemunha em razão da idade?", "v": "Quem tiver menos de 16 anos.", "b": "CPC, art. 447, § 1º, III"},
{"id": "tj_cpc_126", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Testemunhas menores, impedidas ou suspeitas podem ser ouvidas?", "v": "Sim, se necessário, mas sem compromisso, e o juiz lhes dá o valor que merecerem.", "b": "CPC, art. 447, §§ 4º e 5º"},
{"id": "tj_cpc_127", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "O advogado intima a testemunha por carta com AR; com que antecedência junta o comprovante?", "v": "Pelo menos 3 dias antes da audiência.", "b": "CPC, art. 455, § 1º"},
{"id": "tj_cpc_128", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Autoridade com prerrogativa não indica dia para depor: após quanto tempo o juiz designa a data?", "v": "Passado 1 mês sem manifestação, preferencialmente na sede do juízo.", "b": "CPC, art. 454, § 2º"},
{"id": "tj_cpc_129", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Em que ordem o juiz inquire as testemunhas? Pode alterar?", "v": "Primeiro as do autor, depois as do réu, separada e sucessivamente; a ordem pode mudar se as partes concordarem.", "b": "CPC, art. 456"},
{"id": "tj_cpc_130", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Em quanto tempo a parte paga a despesa da testemunha com o comparecimento?", "v": "Logo que arbitrada, ou deposita em cartório dentro de 3 dias.", "b": "CPC, art. 462"},
{"id": "tj_cpc_131", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Nomeado o perito, qual o prazo das partes para arguir impedimento, indicar assistente e apresentar quesitos?", "v": "15 dias da intimação do despacho de nomeação.", "b": "CPC, art. 465, § 1º"},
{"id": "tj_cpc_132", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Ciente da nomeação, em quanto tempo o perito apresenta proposta de honorários, currículo e contatos?", "v": "5 dias; as partes falam sobre os honorários em prazo comum de 5 dias.", "b": "CPC, art. 465, §§ 2º e 3º"},
{"id": "tj_cpc_133", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Quanto dos honorários periciais pode ser pago no início dos trabalhos?", "v": "Até 50%; o restante só ao final, após o laudo e os esclarecimentos.", "b": "CPC, art. 465, § 4º"},
{"id": "tj_cpc_134", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Perito substituído: em quanto tempo devolve os valores e qual a sanção se não o fizer?", "v": "15 dias; senão fica impedido de atuar como perito judicial por 5 anos.", "b": "CPC, art. 468, § 2º"},
{"id": "tj_cpc_135", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Por quanto tempo o juiz pode prorrogar o prazo do laudo, e quantas vezes?", "v": "Uma única vez, pela metade do prazo originalmente fixado.", "b": "CPC, art. 476"},
{"id": "tj_cpc_136", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Com que antecedência mínima o perito protocola o laudo antes da audiência?", "v": "Pelo menos 20 dias antes da audiência de instrução e julgamento.", "b": "CPC, art. 477"},
{"id": "tj_cpc_137", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Qual o prazo para as partes falarem sobre o laudo e para o perito esclarecer pontos divergentes?", "v": "15 dias comuns para as partes (e pareceres dos assistentes); 15 dias para o perito esclarecer.", "b": "CPC, art. 477, §§ 1º e 2º"},
{"id": "tj_cpc_138", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "Com que antecedência o perito ou o assistente é intimado para comparecer à audiência?", "v": "Pelo menos 10 dias, por meio eletrônico.", "b": "CPC, art. 477, § 4º"},
{"id": "tj_cpc_139", "d": "Direito Processual Civil", "t": "Provas em espécie", "r": "1", "f": "A segunda perícia substitui a primeira?", "v": "Não; o juiz aprecia o valor de ambas.", "b": "CPC, art. 480, § 3º"},
{"id": "tj_cpc_140", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Por quanto tempo de paralisação ou abandono o processo é extinto sem resolução do mérito?", "v": "Parado por mais de 1 ano por negligência das partes, ou abandono pelo autor por mais de 30 dias; antes, a parte é intimada pessoalmente para suprir a falta em 5 dias.", "b": "CPC, art. 485, II, III e § 1º"},
{"id": "tj_cpc_141", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Até quando o autor pode desistir da ação?", "v": "Até a sentença.", "b": "CPC, art. 485, § 5º"},
{"id": "tj_cpc_142", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Apelada a sentença sem resolução de mérito, qual o prazo de retratação do juiz?", "v": "5 dias.", "b": "CPC, art. 485, § 7º"},
{"id": "tj_cpc_143", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Quantas extinções por abandono geram perempção?", "v": "3; o autor não pode propor nova ação com o mesmo objeto, mas pode alegar o direito em defesa.", "b": "CPC, art. 486, § 3º"},
{"id": "tj_cpc_144", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Prescrição e decadência podem ser reconhecidas sem ouvir as partes?", "v": "Não, salvo na improcedência liminar do art. 332, § 1º.", "b": "CPC, art. 487, parágrafo único"},
{"id": "tj_cpc_145", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Publicada a sentença, em que casos o juiz pode alterá-la?", "v": "Para corrigir inexatidões materiais ou erros de cálculo, e por embargos de declaração.", "b": "CPC, art. 494"},
{"id": "tj_cpc_146", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "A hipoteca judiciária é afastada por recurso com efeito suspensivo?", "v": "Não; a decisão a produz mesmo impugnada por recurso com efeito suspensivo.", "b": "CPC, art. 495, § 1º, III"},
{"id": "tj_cpc_147", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Quais sentenças estão sujeitas à remessa necessária?", "v": "As proferidas contra a União, Estados, DF, Municípios e suas autarquias e fundações de direito público, e as que acolhem embargos à execução fiscal.", "b": "CPC, art. 496"},
{"id": "tj_cpc_148", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Abaixo de que valores não há remessa necessária?", "v": "1.000 salários mínimos (União); 500 (Estados, DF e Municípios capitais); 100 (demais Municípios), incluídas autarquias e fundações.", "b": "CPC, art. 496, § 3º"},
{"id": "tj_cpc_149", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Na liquidação pelo procedimento comum, qual o prazo de contestação do requerido?", "v": "15 dias, intimado na pessoa de seu advogado.", "b": "CPC, art. 511"},
{"id": "tj_cpc_150", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Requerido o cumprimento após 1 ano do trânsito em julgado, como o devedor é intimado?", "v": "Pessoalmente, por carta com aviso de recebimento ao endereço dos autos.", "b": "CPC, art. 513, § 4º"},
{"id": "tj_cpc_151", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Sentença penal, arbitral ou estrangeira homologada: qual o prazo após a citação do devedor no juízo cível?", "v": "15 dias, para cumprimento ou liquidação.", "b": "CPC, art. 515, § 1º"},
{"id": "tj_cpc_152", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Quando a sentença transitada pode ser protestada, e qual o prazo para a certidão?", "v": "Depois do prazo de pagamento voluntário do art. 523; a certidão de teor sai em 3 dias.", "b": "CPC, art. 517 e § 2º"},
{"id": "tj_cpc_153", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "No cumprimento definitivo de quantia certa, qual o prazo de pagamento e o acréscimo se não pagar?", "v": "15 dias; sem pagamento, multa de 10% e honorários de 10%.", "b": "CPC, art. 523 e § 1º"},
{"id": "tj_cpc_154", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Pagamento parcial no prazo do art. 523: sobre o que incidem multa e honorários?", "v": "Sobre o restante.", "b": "CPC, art. 523, § 2º"},
{"id": "tj_cpc_155", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "A multa e os honorários do art. 523, § 1º incidem no cumprimento provisório?", "v": "Sim, são devidos no cumprimento provisório de sentença de quantia certa.", "b": "CPC, art. 520, § 2º"},
{"id": "tj_cpc_156", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Qual o prazo para impugnação ao cumprimento de sentença, e depende de penhora?", "v": "15 dias após o fim do prazo de pagamento voluntário, sem penhora nem nova intimação, nos próprios autos.", "b": "CPC, art. 525"},
{"id": "tj_cpc_157", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Alegado excesso de execução sem indicar o valor correto, o que ocorre?", "v": "A impugnação é rejeitada liminarmente se esse for seu único fundamento; havendo outro, o excesso não é examinado.", "b": "CPC, art. 525, §§ 4º e 5º"},
{"id": "tj_cpc_158", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "A impugnação ao cumprimento de sentença suspende a execução?", "v": "Não automaticamente; o juiz pode dar efeito suspensivo a pedido, com juízo garantido, fundamentos relevantes e risco de grave dano.", "b": "CPC, art. 525, § 6º"},
{"id": "tj_cpc_159", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Réu que deposita espontaneamente o valor antes de ser intimado: prazo do autor e consequência de depósito insuficiente?", "v": "Autor fala em 5 dias; se insuficiente, incidem multa de 10% e honorários de 10% sobre a diferença.", "b": "CPC, art. 526, §§ 1º e 2º"},
{"id": "tj_cpc_160", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "No cumprimento de sentença de alimentos, qual o prazo do executado e a duração da prisão?", "v": "3 dias para pagar, provar que pagou ou justificar; prisão de 1 a 3 meses se não pagar ou a justificativa for rejeitada.", "b": "CPC, art. 528 e § 3º"},
{"id": "tj_cpc_161", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Qual débito alimentar autoriza a prisão civil?", "v": "Até as 3 prestações anteriores ao ajuizamento da execução e as que vencerem durante o processo.", "b": "CPC, art. 528, § 7º"},
{"id": "tj_cpc_162", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Somado à pensão, até quanto dos ganhos líquidos pode ser descontado do executado de alimentos?", "v": "Até 50%.", "b": "CPC, art. 529, § 3º"},
{"id": "tj_cpc_163", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Qual o prazo da Fazenda Pública para impugnar o cumprimento de sentença?", "v": "30 dias, nos próprios autos.", "b": "CPC, art. 535", "p": "Não confundir com os 15 dias da impugnação do particular (art. 525)."},
{"id": "tj_cpc_164", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Em quanto tempo se paga a obrigação de pequeno valor contra a Fazenda no CPC?", "v": "Em 2 meses da entrega da requisição, por depósito em banco oficial.", "b": "CPC, art. 535, § 3º, II"},
{"id": "tj_cpc_165", "d": "Direito Processual Civil", "t": "Sentença, remessa necessária, coisa julgada e cumprimento de sentença", "r": "1", "f": "Quantos oficiais cumprem o mandado de busca e apreensão de pessoas e coisas?", "v": "2 oficiais de justiça.", "b": "CPC, art. 536, § 2º"},
{"id": "tj_cpc_166", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Qual o prazo para interpor recursos e responder a eles no CPC?", "v": "15 dias, exceto embargos de declaração.", "b": "CPC, art. 1.003, § 5º", "p": "Embargos de declaração: 5 dias (art. 1.023)."},
{"id": "tj_cpc_167", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "No recurso enviado pelo correio, que data define a tempestividade?", "v": "A data de postagem.", "b": "CPC, art. 1.003, § 4º"},
{"id": "tj_cpc_168", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "O recorrente precisa da anuência do recorrido para desistir do recurso?", "v": "Não; pode desistir a qualquer tempo, sem anuência do recorrido ou dos litisconsortes.", "b": "CPC, art. 998"},
{"id": "tj_cpc_169", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "O recurso de um litisconsorte aproveita aos demais?", "v": "Sim, salvo se os interesses forem distintos ou opostos.", "b": "CPC, art. 1.005"},
{"id": "tj_cpc_170", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Certificado o trânsito em julgado, em quanto tempo o escrivão baixa os autos?", "v": "Em 5 dias, independentemente de despacho.", "b": "CPC, art. 1.006"},
{"id": "tj_cpc_171", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Preparo insuficiente: qual o prazo para complementar? E se não houve comprovação do preparo?", "v": "Insuficiente: 5 dias para suprir. Não comprovado: recolhimento em dobro, sob pena de deserção.", "b": "CPC, art. 1.007, §§ 2º e 4º", "p": "Se, no recolhimento em dobro, ainda houver insuficiência, não se admite complementar (§ 5º)."},
{"id": "tj_cpc_172", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Questões suscitadas nas contrarrazões de apelação: em quanto tempo o recorrente se manifesta?", "v": "15 dias.", "b": "CPC, art. 1.009, § 2º"},
{"id": "tj_cpc_173", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Quem faz o juízo de admissibilidade da apelação?", "v": "Não o juiz de 1º grau: após as contrarrazões, os autos sobem ao tribunal independentemente de juízo de admissibilidade.", "b": "CPC, art. 1.010, § 3º"},
{"id": "tj_cpc_174", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Quais sentenças produzem efeitos logo após publicadas, sem efeito suspensivo da apelação?", "v": "As que homologam divisão ou demarcação, condenam a alimentos, extinguem sem mérito ou rejeitam embargos do executado, julgam procedente instituição de arbitragem, confirmam, concedem ou revogam tutela provisória, ou decretam interdição.", "b": "CPC, art. 1.012, § 1º", "p": "Regra geral: a apelação tem efeito suspensivo (art. 1.012)."},
{"id": "tj_cpc_175", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Reformando sentença que reconheceu prescrição ou decadência, o tribunal devolve o processo ao 1º grau?", "v": "Não, se possível julga o mérito diretamente.", "b": "CPC, art. 1.013, § 4º"},
{"id": "tj_cpc_176", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Questões de fato não propostas no 1º grau podem ser levadas na apelação?", "v": "Sim, se a parte provar que não as propôs por motivo de força maior.", "b": "CPC, art. 1.014"},
{"id": "tj_cpc_177", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Em autos físicos, em quanto tempo o agravante junta cópia do agravo de instrumento no 1º grau?", "v": "3 dias da interposição.", "b": "CPC, art. 1.018, § 2º"},
{"id": "tj_cpc_178", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Recebido o agravo de instrumento, qual o prazo do relator e o de resposta do agravado?", "v": "Relator: 5 dias (pode dar efeito suspensivo ou antecipar a tutela recursal). Agravado: 15 dias para responder.", "b": "CPC, art. 1.019"},
{"id": "tj_cpc_179", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Em que prazo o relator pede dia para julgar o agravo de instrumento?", "v": "Não superior a 1 mês da intimação do agravado.", "b": "CPC, art. 1.020"},
{"id": "tj_cpc_180", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Qual a multa no agravo interno declarado manifestamente inadmissível ou improcedente por unanimidade?", "v": "Entre 1% e 5% do valor atualizado da causa; outro recurso depende de depósito prévio, salvo Fazenda e beneficiário da gratuidade (pagam ao final).", "b": "CPC, art. 1.021, §§ 4º e 5º"},
{"id": "tj_cpc_181", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Qual o prazo dos embargos de declaração, e há preparo?", "v": "5 dias, com indicação do erro, obscuridade, contradição ou omissão; não há preparo.", "b": "CPC, art. 1.023"},
{"id": "tj_cpc_182", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Quando o embargado é ouvido nos embargos de declaração, e em quanto tempo o juiz os julga?", "v": "É ouvido em 5 dias se o acolhimento puder modificar a decisão; o juiz julga em 5 dias.", "b": "CPC, arts. 1.023, § 2º, e 1.024"},
{"id": "tj_cpc_183", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Embargos de declaração suspendem ou interrompem o prazo de outros recursos?", "v": "Interrompem; e não têm efeito suspensivo.", "b": "CPC, art. 1.026", "p": "Interrompem (prazo recomeça), não apenas suspendem."},
{"id": "tj_cpc_184", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Qual a multa por embargos de declaração protelatórios e na reiteração?", "v": "Até 2% do valor atualizado da causa; na reiteração, até 10%, e outro recurso fica condicionado ao depósito.", "b": "CPC, art. 1.026, §§ 2º e 3º"},
{"id": "tj_cpc_185", "d": "Direito Processual Civil", "t": "Recursos: teoria geral, apelação, agravos e embargos de declaração", "r": "1", "f": "Quando não se admitem novos embargos de declaração?", "v": "Se os 2 anteriores tiverem sido considerados protelatórios.", "b": "CPC, art. 1.026, § 4º"},
{"id": "tj_cpc_186", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "Qual o teto de valor da causa no Juizado Especial Cível?", "v": "40 salários mínimos; o mesmo vale para possessórias de imóveis e execução de títulos extrajudiciais.", "b": "Lei 9.099/95, art. 3º, I, IV e § 1º, II"},
{"id": "tj_cpc_187", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "Optar pelo Juizado Cível com crédito acima do teto tem que consequência?", "v": "Renúncia ao excedente, salvo se houver conciliação.", "b": "Lei 9.099/95, art. 3º, § 3º"},
{"id": "tj_cpc_188", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "De onde são recrutados os juízes leigos no JEC e no Juizado da Fazenda Pública?", "v": "Entre advogados com mais de 5 anos de experiência (JEC) e com mais de 2 anos (Fazenda Pública).", "b": "Lei 9.099/95, art. 7º; Lei 12.153/09, art. 15, § 1º", "p": "5 anos na Lei 9.099; 2 anos na Lei 12.153."},
{"id": "tj_cpc_189", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "Até que valor a parte pode ir ao JEC sem advogado?", "v": "Até 20 salários mínimos; acima disso a assistência é obrigatória.", "b": "Lei 9.099/95, art. 9º"},
{"id": "tj_cpc_190", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "A partir de que idade se pode ser autor no JEC sem assistência?", "v": "Maior de 18 anos, inclusive para conciliar.", "b": "Lei 9.099/95, art. 8º, § 2º"},
{"id": "tj_cpc_191", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "Como se contam os prazos no JEC, inclusive os recursais?", "v": "Só em dias úteis.", "b": "Lei 9.099/95, art. 12-A"},
{"id": "tj_cpc_192", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "Registrado o pedido no JEC, em quanto tempo deve ocorrer a sessão de conciliação?", "v": "Em 15 dias.", "b": "Lei 9.099/95, art. 16"},
{"id": "tj_cpc_193", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "Pedidos cumulados no JEC: qual o requisito?", "v": "Devem ser conexos e a soma não pode passar de 40 salários mínimos.", "b": "Lei 9.099/95, art. 15"},
{"id": "tj_cpc_194", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "Qual o teto do Juizado Especial da Fazenda Pública e como se conta em obrigações vincendas?", "v": "60 salários mínimos; em vincendas, a soma de 12 parcelas e das vencidas não pode ultrapassá-lo.", "b": "Lei 12.153/09, art. 2º e § 2º"},
{"id": "tj_cpc_195", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "A competência do Juizado da Fazenda Pública é absoluta ou relativa?", "v": "Absoluta, onde estiver instalado.", "b": "Lei 12.153/09, art. 2º, § 4º"},
{"id": "tj_cpc_196", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "A Fazenda tem prazo diferenciado no seu Juizado? Com que antecedência é citada para a conciliação?", "v": "Não há prazo diferenciado, nem para recurso; a citação ocorre com no mínimo 30 dias de antecedência.", "b": "Lei 12.153/09, art. 7º"},
{"id": "tj_cpc_197", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "Com que antecedência o perito do Juizado da Fazenda apresenta o laudo?", "v": "Até 5 dias antes da audiência.", "b": "Lei 12.153/09, art. 10"},
{"id": "tj_cpc_198", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "No Juizado da Fazenda, em quanto tempo se paga a obrigação de pequeno valor?", "v": "Em até 60 dias da entrega da requisição, sem precatório; desatendida, o juiz determina o sequestro de imediato.", "b": "Lei 12.153/09, art. 13, I e § 1º"},
{"id": "tj_cpc_199", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "Sem lei local, qual o limite da obrigação de pequeno valor para Estados/DF e para Municípios?", "v": "40 salários mínimos para Estados e DF; 30 para Municípios.", "b": "Lei 12.153/09, art. 13, § 3º"},
{"id": "tj_cpc_200", "d": "Direito Processual Civil", "t": "Juizados Especiais Cíveis e da Fazenda Pública", "r": "1", "f": "Como são compostas as Turmas Recursais e qual o mandato?", "v": "Por juízes em exercício no 1º grau, com mandato de 2 anos.", "b": "Lei 12.153/09, art. 17"}
]);
